const records = [];

const features = $('Source 1').first().json.features || [];

// Initialize band data structures
const bands = {
  minor: { count: 0, maxMag: -Infinity, maxDepth: -Infinity },
  moderate: { count: 0, maxMag: -Infinity, maxDepth: -Infinity },
  major: { count: 0, maxMag: -Infinity, maxDepth: -Infinity }
};

// Process each earthquake event
features.forEach(feature => {
  const mag = feature.properties.mag;
  const depth = feature.geometry.coordinates[2];
  let bandName;

  if (mag < 4.0) {
    bandName = 'minor';
  } else if (mag >= 4.0 && mag <= 5.0) {
    bandName = 'moderate';
  } else {
    bandName = 'major';
  }

  const bandData = bands[bandName];
  bandData.count++;
  if (mag > bandData.maxMag) bandData.maxMag = mag;
  if (depth > bandData.maxDepth) bandData.maxDepth = depth;
});

// Generate output records for non-empty bands
Object.entries(bands).forEach(([bandName, data]) => {
  if (data.count > 0) {
    records.push({
      magnitude_band: bandName,
      event_count: data.count,
      max_magnitude: data.maxMag,
      max_depth_km: data.maxDepth
    });
  }
});

return [{ json: { records } }];
